    "manzilHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);\">প্রয়োজনীয় দোয়া ও আমল: সূরা আল-ইখলাস</div>\n      <div style=\"color: #93c5fd; font-size: 0.9rem; font-weight: bold; margin-top: 0.5rem;\">ইখলাস: আল্লাহ এক ও অমুখাপেক্ষী। ফালাক: আমি আশ্রয় চাই ঊষার রবের কাছে সকল অনিষ্ট থেকে। নাস: আমি আশ্রয় চাই মানুষের রবের কাছে কুমন্ত্রণাদাতার অনিষ্ট থেকে।</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">مِن شَرِّ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">মিন শাররি</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">অনিষ্ট থেকে</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">الْوَسْوَاسِ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">আল-ওয়াসওয়াসি</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">কুমন্ত্রণাদাতার</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">يُوَسْوِسُ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ইউওয়াসউইসু</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">যে কুমন্ত্রণা দেয়</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">فِي صُدُورِ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ফী সুদূরি</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">অন্তরে</div>\n        \n      </div>\n    \n      </div>\n    </div>\n  ",
