    "manzilHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);\">প্রয়োজনীয় দোয়া ও আমল: সূরা আল-বাকারাহ (১-৫)</div>\n      <div style=\"color: #93c5fd; font-size: 0.9rem; font-weight: bold; margin-top: 0.5rem;\">কুরআনের শুরু এবং হিদায়াতের বর্ণনা।</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَالَّذِينَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়াল্লাযীনা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং যারা</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">يُؤْمِنُونَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ইউমিনুনা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">ঈমান আনে</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">بِمَا</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">বিমা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">তার প্রতি যা</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">أُنزِلَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">উনযিলা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">নাজিল হয়েছে</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">إِلَيْكَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ইলাইকা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আপনার প্রতি</div>\n        \n      </div>\n    \n      </div>\n    </div>\n  ",
    "surahName": "সূরা আল-হুমাযাহ",
