    "surahHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\">আজকের সূরা: সূরা আল-আসর</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">لَفِي خُسْرٍ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">লাফী খুসর</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">ক্ষতির মধ্যে</div>\n      </div>\n    \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">إِلَّا الَّذِينَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ইল্লাল্লাযীনা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">তারা ছাড়া যারা</div>\n      </div>\n    \n      </div>\n    </div>\n  ",
    "manzilHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);\">প্রয়োজনীয় দোয়া ও আমল: সূরা বাকারাহ (২৫৬-২৫৭)</div>\n      <div style=\"color: #93c5fd; font-size: 0.9rem; font-weight: bold; margin-top: 0.5rem;\">দ্বীনের ব্যাপারে জোর-জবরদস্তি নেই।</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَيُؤْمِن</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়া ইউমিন</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং ঈমান আনবে</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">بِاللَّهِ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">বিল্লাহি</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আল্লাহর প্রতি</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">فَقَدِ اسْتَمْسَكَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ফাকাদিস তামসাকা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">সে আঁকড়ে ধরল</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">بِالْعُرْوَةِ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">বিল উরওয়াতিল</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">হাতল</div>\n        \n      </div>\n    \n      </div>\n    </div>\n  ",
