    "surahHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\">আজকের সূরা: সূরা আল-বাইয়্যিনাহ (Surah Al-Bayyinah)</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">লাম ইয়াকুনিল্লাযীনা কাফারূ মিন আহলিল কিতাবি ওয়াল মুশরিকীনা মুনফাক্কীনা হাত্তা তা'তিয়াহুমুল বাইয়্যিনাহ</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আহলে কিতাব ও মুশরিকদের কাফেররা (কুফর থেকে) নিবৃত্ত হওয়ার ছিল না, যে পর্যন্ত না তাদের কাছে সুস্পষ্ট প্রমাণ আসে।</div>\n      </div>\n    \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">رَسُولٌ مِّنَ اللَّهِ يَتْلُو صُحُفًا مُّطَهَّرَةً</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">রাসূলুম মিনাল্লাহি ইয়াতলূ সুহুফাম মুতাহহারাহ</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আল্লাহর পক্ষ থেকে একজন রাসূল, যিনি পবিত্র গ্রন্থসমূহ পাঠ করেন।</div>\n      </div>\n    \n      </div>\n    </div>\n  ",
    "manzilHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);\">প্রয়োজনীয় দোয়া ও আমল: আয়াতুল কুরসি ও বাকারাহ ১৬৩</div>\n      <div style=\"color: #93c5fd; font-size: 0.9rem; font-weight: bold; margin-top: 0.5rem;\">আল্লাহর একত্ববাদ ও ক্ষমতার শ্রেষ্ঠ আয়াত।</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">لَا تَأْخُذُهُ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">লা তাখুযুহু</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">তাঁকে স্পর্শ করে না</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">سِنَةٌ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">সিনাতুন</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">তন্দ্রা</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَلَا نَوْمٌ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়া লা নাওম</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং ঘুমও নয়</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">لَّهُ مَا</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">লাহু মা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">তাঁরই যা কিছু</div>\n        \n      </div>\n    \n      <div style=\"background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">فِي السَّمَاوَاتِ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ফিস সামাওয়াতি</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আসমানসমূহে রয়েছে</div>\n        \n      </div>\n    \n      </div>\n    </div>\n  ",
