    "surahHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\">আজকের সূরা: সূরা আশ-শারহ (Surah Ash-Sharh)</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">আলাম নাশরাহ লাকা সাদরাক</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">আমি কি আপনার বক্ষ আপনার জন্য প্রশস্ত করে দিইনি?</div>\n      </div>\n    \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَوَضَعْنَا عَنكَ وِزْرَكَ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়া ওয়াদা'না আংকা ওয়াযরাক</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং আমি আপনার থেকে আপনার বোঝা নামিয়ে দিয়েছি।</div>\n      </div>\n    \n      </div>\n    </div>\n  ",
