    "surahHtml": "\n    <div class=\"content-section\">\n      <div class=\"section-badge\">আজকের সূরা: সূরা আল-লাইল (Surah Al-Lail)</div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; margin-top: 1rem;\">\n        \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَاللَّيْلِ إِذَا يَغْشَىٰ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়াল লাইলি ইযা ইয়াগশা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">শপথ রাতের, যখন তা আচ্ছন্ন করে।</div>\n      </div>\n    \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَالنَّهَارِ إِذَا تَجَلَّىٰ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়ান নাহারি ইযা তাজাল্লা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং শপথ দিনের, যখন তা আলোকিত হয়।</div>\n      </div>\n    \n      <div style=\"background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); padding: 1rem; border-radius: 8px; text-align: center; margin-bottom: 0.5rem;\">\n        <div style=\"font-size: 1.8rem; font-weight: bold; color: var(--primary-color); margin-bottom: 0.5rem;\">وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ</div>\n        <div style=\"color: var(--secondary-color); font-size: 0.9rem; font-weight: 600; margin-bottom: 0.2rem;\">ওয়া মা খালাকায যাকারা ওয়াল উনসা</div>\n        <div style=\"color: var(--text-muted); font-size: 0.9rem;\">এবং শপথ তাঁর, যিনি নর ও নারী সৃষ্টি করেছেন।</div>\n      </div>\n    \n      </div>\n    </div>\n  ",
